SELECT CASE WHEN stock_qty >= 447 THEN 'high' WHEN stock_qty >= 104 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, COUNT(*) AS cnt, SUM(CASE WHEN category = 'Sports' THEN stock_qty ELSE 0 END) AS sports_stock_qty, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(brand))) AS brand_values FROM products GROUP BY CASE WHEN stock_qty >= 447 THEN 'high' WHEN stock_qty >= 104 THEN 'mid' ELSE 'low' END;
